import{_ as d,l as t,o as a,c as s,v as i,p as n,x as r,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"设备模型与驱动绑定","description":"","frontmatter":{"title":"设备模型与驱动绑定","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/device-model-binding.md","filePath":"cs/device-model-binding.md","lastUpdated":1789023840000}'),h={name:"cs/device-model-binding.md"};function m(u,e,b,f,v,_){const o=t("Mermaid");return a(),s("div",null,[e[1]||(e[1]=i('<h1 id="设备模型与驱动绑定" tabindex="-1">设备模型与驱动绑定 <a class="header-anchor" href="#设备模型与驱动绑定" aria-label="Permalink to &quot;设备模型与驱动绑定&quot;">​</a></h1><div class="epigraph"><p>Linux 设备模型用 bus/device/driver 三元组：匹配成功则 probe，sysfs 导出属性，解绑则 remove。</p><footer>—— 据 Corbet, Rubini, Kroah-Hartman, <em>Linux Device Drivers</em>；内核 driver-model 文档</footer></div><p><a href="/cs/devicetree-acpi">DT/ACPI</a> 造出 <code>device</code>。缺口是 <strong>绑定</strong>：匹配表、probe、与 <a href="/cs/device-nodes">设备节点</a> 的 cdev 注册。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PCI：vendor/device id。平台设备：DT compatible。匹配后 <code>probe</code> 申请 IRQ、ioremap、注册子系统（块、net）。缺口：延迟探测、绑定失败回滚；sysfs <code>unbind</code>。本课不把每个总线类型写成清单。</p><p><span class="marginnote">uevent 通知 udev 后课。对象是内核对象图，不是硬件原理图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注册 driver → 对新 device 匹配 → probe。对照 <a href="/cs/fuse">FUSE</a>：用户实现操作；这里是内核 C。对照 <a href="/cs/napi">NAPI</a>：probe 里注册 napi。对照 LSM：probe 仍要能力。</p>',8)),(a(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUS%5B%22%E6%80%BB%E7%BA%BF%22%5D%20--%3E%20DEV%5B%22device%22%5D%0A%20%20BUS%20--%3E%20DRV%5B%22driver%22%5D%0A%20%20DEV%20--%3E%20ID%5B%22id%2Fcompatible%20%E5%8C%B9%E9%85%8D%22%5D%0A%20%20ID%20--%3E%20PROBE%5B%22probe%20%E8%B5%84%E6%BA%90%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>设备模型让热插、电源、sysfs 有统一骨架，驱动只填总线相关。它是「一切皆文件」在设备侧的内核实现。不要写成 Windows INF 课。与 <a href="/cs/dma-coherence">IOMMU</a>：probe 时设 DMA 掩码。</p><p>循环依赖（设备等时钟、时钟等设备）靠框架延迟。</p><p>实现上：deferred probe 解决时钟与设备的循环依赖，但会让「驱动已加载却无节点」持续一段时间。sysfs unbind 可拆驱动，热升级用这个。模块卸载要 refcount 为零。 读法上只引用<a href="/cs/devicetree-acpi">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>设备模型与驱动绑定</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 component helper 的全部。不保证用户态驱动（VFIO）走同一 probe。下一课字符设备与 ioctl。</p><p>版本字段会变，课序钉的是机制对象「设备模型与驱动绑定」，不是某一主线内核的结构体名。 后课默认：匹配则 probe 并导出 sysfs。cdev 与 ioctl ABI，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>bus 匹配 device 与 driver，probe 申请资源。</li><li>sysfs 是该模型的用户可见面。</li><li>字符设备 ioctl 是下一课。</li><li>出处：LDD3；Linux driver-model。</li></ul>',11))])}const E=d(h,[["render",m]]);export{B as __pageData,E as default};
